import json
import itertools

def solve_puzzle():
    # Define the puzzle parameters
    houses = [1, 2]  # left to right
    names = ["Eric", "Arnold"]
    hobbies = ["gardening", "photography"]
    pets = ["cat", "dog"]
    heights = ["short", "very short"]

    solutions = []

    # Helper to get the house index (1-based) of a given value in a mapping dict
    def house_of_value(mapping, value):
        for h, v in mapping.items():
            if v == value:
                return h
        return None

    # Iterate over all possible assignments with pruning using constraints
    for name_perm in itertools.permutations(names):
        names_by_house = {house: name_perm[i] for i, house in enumerate(houses)}
        eric_house = house_of_value(names_by_house, "Eric")

        for height_perm in itertools.permutations(heights):
            heights_by_house = {house: height_perm[i] for i, house in enumerate(houses)}

            # Clue 2: Eric is the person who is very short.
            if heights_by_house[eric_house] != "very short":
                continue

            for hobby_perm in itertools.permutations(hobbies):
                hobbies_by_house = {house: hobby_perm[i] for i, house in enumerate(houses)}

                # Clue 1: The person who is very short is the photography enthusiast.
                very_short_house = house_of_value(heights_by_house, "very short")
                if hobbies_by_house[very_short_house] != "photography":
                    continue

                for pet_perm in itertools.permutations(pets):
                    pets_by_house = {house: pet_perm[i] for i, house in enumerate(houses)}

                    # Clue 3: The person who has a cat is somewhere to the right of the person who is very short.
                    cat_house = house_of_value(pets_by_house, "cat")
                    if not (cat_house > very_short_house):
                        continue

                    # If all constraints are satisfied, record the solution
                    solution = {
                        "House": {h: str(h) for h in houses},
                        "Name": names_by_house,
                        "Hobby": hobbies_by_house,
                        "Pet": pets_by_house,
                        "Height": heights_by_house,
                    }
                    solutions.append(solution)

    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    # Assuming unique solution; take the first
    sol = solutions[0]

    # Prepare JSON output in the specified structure
    header = ["House", "Name", "Hobby", "Pet", "Height"]
    rows = []
    for h in houses:
        row = [str(h), sol["Name"][h], sol["Hobby"][h], sol["Pet"][h], sol["Height"][h]]
        rows.append(row)

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), ensure_ascii=False))
